package alphametics

import "testing"

func TestExtra(t *testing.T) {
	// no-solution puzzle
	if _, err := Solve("AA + BB == CC"); err == nil {
		t.Fatal("expected error for AA+BB==CC")
	}
	// single letter
	m, err := Solve("A == A")
	if err != nil || m["A"] < 0 || m["A"] > 9 {
		t.Fatalf("single letter: %v %v", m, err)
	}
	// leading zero in addend/result must be rejected as a solution
	if _, err := Solve("ACA + DD == BD"); err == nil {
		t.Fatal("expected error for leading zero puzzle")
	}
	// result longer than addends, must both be valid
	if _, err := Solve("A + A == BA"); err == nil {
		t.Fatal("expected error for A+A==BA")
	}
}
EOF
